package com.cdg.ordersupport.auth;
import com.cdg.ordersupport.auth.dto.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/register") ResponseEntity<AuthResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(r));} @PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);} @GetMapping("/me") AuthResponse me(Authentication a){return service.me((String)a.getPrincipal());} }
